-- A25: pré-autorização sem dados de arquivo; impede escrita em storage antes da validação contextual.
create or replace function public.subdivision_authorize_buyer_attachment_upload(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_attachment_intent_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_intent_id uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select id into v_intent_id from public.subdivision_buyer_attachment_intents where id=p_attachment_intent_id and organization_id=p_organization_id and storage_key is null; if v_intent_id is null then raise exception using errcode='42501',message='SUBDIVISION_ATTACHMENT_UPLOAD_CONTEXT_DENIED';end if;return v_intent_id;end;$$;
revoke all on function public.subdivision_authorize_buyer_attachment_upload(uuid,uuid,public.operating_module,text,uuid) from public,anon,authenticated;
grant execute on function public.subdivision_authorize_buyer_attachment_upload(uuid,uuid,public.operating_module,text,uuid) to service_role;
